const entities=(type:string)=>snap.entities.filter(e=>e.type===type);
const accounts=()=>entities('accounts').filter(e=>!e.fields.deleted_at);
const transactions=()=>entities('transactions').filter(e=>!e.fields.deleted_at);
const getT=(id:string)=>entities('transactions').find(t=>t.id===id)!;
const effect=(id:string)=>entities('consumption_effects').find(e=>e.fields.transaction_id===id);
const moves=(id:string)=>entities('balance_movements').filter(e=>e.fields.transaction_id===id&&e.fields.amount!==0);
const category=(id:string)=>String(effect(id)?.fields.category_id||'其他');
const accountName=(id:any)=>accounts().find(a=>a.id===id)?.fields.name||'待补认账户';
const accountLabel=(t:Entity)=>{const ms=moves(t.id);return ms.length?ms.map(m=>accountName(m.fields.account_id)).join(' → '):t.fields.event_type==='PURCHASE'&&t.fields.status==='SUCCESS'?'亲情卡 / 他人代付':'无资金变动';};
function inMonth(t:Entity,m=month){return monthOf(new Date(t.fields.occurred_at as string))===m;}
function period(m=month){const [y,n]=m.split('-').map(Number);return [new Date(Date.UTC(y,n-1,1)-8*3600000).toISOString(),new Date(Date.UTC(y,n,1)-8*3600000).toISOString()];}
function total(m=month){if(snap.conflicts.length)return null;return consumptionInPeriod(snap,...period(m) as [string,string]);}
function balance(a:Entity){try{return accountBalance(snap,a.id,new Date().toISOString()).balance;}catch{return null;}}
function balanceStatus(a:Entity){if(snap.conflicts.length)return '存在同步冲突，暂不能计算';if(a.fields.balance_tracking==='DISABLED')return '已关闭余额跟踪';if(a.fields.balance_state==='UNINITIALIZED')return '尚未设置期初余额';if(Date.parse(String(a.fields.opening_balance_at))>Date.now())return '期初时刻尚未到达：'+formatTime(a.fields.opening_balance_at);if(balance(a)===null)return '余额计算异常，请核验记录';return '期初 '+formatTime(a.fields.opening_balance_at);}
const activeMonth=()=>transactions().filter(t=>inMonth(t)&&t.fields.status==='SUCCESS');
