function budgetDialog(){modal('月消费预算',`<form id="budget-form"><label>每月预算 · 元<input name="budget" type="number" min="0.01" step="0.01" value="${state.settings.budget===null?'':state.settings.budget/100}" required></label><p class="footnote">按真实消费扣减，退款冲减发生月消费。预算设置保存在本机。</p><div class="modal-actions"><button type="button" class="secondary" data-action="disable-budget">不设预算</button><button type="submit" class="primary">保存预算</button></div></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await settings({budget:money(formData(e.target as HTMLFormElement).budget)});await refresh();close();});};}
