async function demo(){if(state.ops.length)throw Error('演示仅能在空账本中开启');await mutate(store=>{const svc=new BusinessAccountingService(store,store.state.device);const [y,m]=month.split('-').map(Number);const opening=new Date(y,m-1,1,0,0,0).toISOString();for(const [id,name,b] of [['demo-bank','日常银行卡',800000],['demo-wechat','微信余额',125000],['demo-alipay','支付宝余额',50000]] as const)svc.execute({kind:'CREATE_ACCOUNT',id,name,accountType:'ASSET',openingBalance:b,openingBalanceAt:opening});const sample=[['巷口咖啡',2800,'餐饮'],['地铁出行',500,'交通'],['周末的鲜花',4500,'生活'],['午餐 · 好好吃饭',3200,'餐饮'],['一本新书',6800,'学习'],['超市采购',12650,'生活'],['朋友小聚',16800,'餐饮'],['日用品补充',8900,'购物'],['电影之夜',4200,'娱乐'],['早餐',1200,'餐饮']];sample.forEach(([name,amount,cat],i)=>svc.execute({kind:'PURCHASE',id:'demo-'+i,name:String(name),amount:Number(amount),occurredAt:new Date(y,m-1,Math.min(i*2+1,new Date(y,m,0).getDate()),12,0).toISOString(),payer:i%2?'demo-bank':'demo-wechat',categoryId:String(cat),note:'虚构示例，用于体验页面'}));store.state.settings.demo=true;store.state.settings.budget=300000;});await refresh();toast('已开启演示账本');}
const actions:Record<string,()=>any>={new:()=>newRecord(),account:()=>accountDialog(),capture, 'import-file':importFile, 'commit-import':()=>commitImport(), 'commit-ready':()=>commitImport(true), 'setup-import-accounts':setupImportAccounts, 'review-refunds':reviewRefunds, 'clear-import':()=>queueAction('deferred'),'select-safe':async()=>{refreshDrafts();const ids=new Set(importIndexes());drafts.forEach((d,i)=>d.selected=ids.has(i)&&!d.issue&&!['committed','linked','ignored','noeffect','deferred'].includes(d.workflow||''));await persistQueue();},'apply-import-account':()=>batchImportAccount(false),'replace-import-account':()=>batchImportAccount(true),'select-import-group':async()=>{for(const i of importIndexes())if(!['linked','committed','noeffect'].includes(drafts[i].workflow||''))drafts[i].selected=true;await persistQueue();},'unselect-import':async()=>{drafts.forEach(d=>d.selected=false);await persistQueue();},'defer-import':()=>queueAction('deferred'),'ignore-import':()=>confirmAction('忽略来源','忽略后重复导入不会再次提示。可在已忽略列表恢复待办。',()=>queueAction('ignored'),'确认忽略'),'restore-import':()=>queueAction('review'),'confirm-import-sponsor':confirmImportSponsor,'confirm-import-type':confirmImportType,'import-audit':importAudit,budget:budgetDialog,sync:syncDialog,trash,demo,'clear-demo':()=>confirmAction('结束演示','演示交易将被清空，然后开始你的个人账本。',async()=>{await mutate(store=>{store.state.ops=[];store.state.pending=[];store.state.batches=[];store.state.envelopes={};store.state.settings.demo=false;store.state.imports=[];store.state.importRevision=(store.state.importRevision||0)+1;});},'开始我的账本'),'select-all':()=>{const list=filteredBills();selected=selected.size===list.length?new Set():new Set(list.map(t=>t.id));render();},deselect:()=>{selected.clear();render();},'batch-category':batchCategory,'batch-delete':()=>confirmAction('移至回收站',`将选中的 ${selected.size} 笔交易移至回收站。有关联退款的原交易需要先处理退款。`,async()=>{await mutate(store=>{const svc=new BusinessAccountingService(store,store.state.device);const sorted=[...selected].sort((a,b)=>Number(['REFUND','RETURN'].includes(String(getT(b).fields.event_type)))-Number(['REFUND','RETURN'].includes(String(getT(a).fields.event_type))));for(const id of sorted)svc.execute({kind:'DELETE_TRANSACTION',transactionId:id,deletedAt:new Date().toISOString()});});selected.clear();},'确认移除'),backup:async()=>download('star-ledger-'+new Date().toISOString().slice(0,10)+'.json',await backup()),restore:async()=>{const file=await chooseFile('.json');if(!file)return;if(file.size>30*1024*1024)throw Error('备份文件过大');const text=await file.text();confirmAction('合并恢复备份','会将备份中的账务记录合并到本机，重复操作会跳过。',async()=>{await restore(text);toast('备份已合并');},'合并恢复');},persist:async()=>toast(await navigator.storage?.persist?.()?'已获准持久存储，仍建议定期备份':'浏览器未授予持久存储，请定期导出备份'),'disable-budget':async()=>{await settings({budget:null});await refresh();close();toast('已关闭预算');},'save-budget':async()=>{await settings({budget:money($<HTMLInputElement>('#budget-input').value)});await refresh();toast('预算已保存');},'add-category':async()=>{const name=$<HTMLInputElement>('#category-name').value.trim();if(!name)return;if(state.settings.categories.includes(name))throw Error('分类已存在');await settings({categories:[...state.settings.categories,name]});await refresh();},'export-csv':()=>{const q=(s:any)=>'"'+String(s??'').replace(/"/g,'""').replace(/^([=+@-])/,'\t$1')+'"';const rows=[['时间','名称','类型','状态','金额元','分类','账户','备注'],...filteredBills().map(t=>[new Date(String(t.fields.occurred_at)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),t.fields.display_name,typeNames[String(t.fields.event_type)],statusNames[String(t.fields.status)],Number(t.fields.display_amount)/100,category(t.id),accountLabel(t),t.fields.note])];download('star-ledger-'+month+'.csv','\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8');},help:()=>modal('开始使用星账',`<ol class="steps"><li><b>导入并设置账户</b><span>导入账单，按渠道新建或绑定已有账户，名称可改，余额以后再补。</span></li><li><b>记下日常消费</b><span>手机从「概览 → 截图记账」选择图片，核对后保存；也能随时手动记一笔。</span></li><li><b>电脑整理账单</b><span>导入微信 / 支付宝 XLSX 或 CSV，自动识别账户、亲情卡和分类；退款先记录，少数关联稍后整理。</span></li><li><b>连接另一台设备</b><span>在设置中填写私有数据仓库和令牌，两端使用相同账本 ID 与恢复密钥。每次点击同步交换修改。</span></li><li><b>定期备份</b><span>导出 JSON 备份。清理浏览器网站数据会删除本机记录。截图识别首次需要网络，网页加载完成后基本记账支持离线。</span></li></ol><p class="footnote">本版不读取旧版网页账本，旧版继续在原链接使用。截图识别需核对；涉及整笔账务的复杂同步冲突会保留记录并暂停合计。</p>`,true)};
document.addEventListener('click',async ev=>{const el=(ev.target as Element).closest<HTMLElement>('button,a[data-page]');if(!el)return;try{if(el.hasAttribute('data-close')){close();return;}const d=el.dataset;if(d.page){close();setPage(d.page);return;}if(d.action){if(app.inert)return;app.inert=true;app.setAttribute('aria-busy','true');try{await actions[d.action]?.();}finally{app.inert=false;app.removeAttribute('aria-busy');}return;}if(d.forgetAlias){confirmAction('停止记忆账户关系','只影响后续识别，不修改历史账单。',async()=>{await raw([ruleCommand(snap.entities,d.forgetAlias!,null)]);});return;}if(d.sourceReview!==undefined){const item=drafts[Number(d.sourceReview)],old=getT(item.transactionId||'');if(old?.fields.status==='PENDING'&&item.status==='SUCCESS'&&old.fields.event_type===item.kind&&old.fields.display_amount===money(item.amount)&&old.fields.occurred_at===sourceUTC(item.date)){newRecord(item,undefined,old);}else reviewSourceChange(Number(d.sourceReview));return;}if(d.linkReturn){linkReturnDialog(d.linkReturn);return;}if(d.correct){correctAmount(d.correct);return;}if(d.detail){detail(d.detail);return;}if(d.account){accountDialog(d.account);return;}if(d.draft!==undefined){newRecord(drafts[Number(d.draft)],Number(d.draft));return;}if(d.refund){refund(d.refund);return;}if(d.delete){confirmAction('移至回收站','此笔交易将从统计中移除，原始凭证仍保留，可从回收站恢复。',async()=>{await business({kind:'DELETE_TRANSACTION',transactionId:d.delete!,deletedAt:new Date().toISOString()});},'确认移除');return;}if(d.restore){await restoreTransaction(d.restore);return;}if(d.bind){bind(d.bind);return;}if(d.meaning){meaning(d.meaning);return;}if(d.settle){const t=getT(d.settle);newRecord({kind:String(t.fields.event_type),name:String(t.fields.display_name),amount:String(Number(t.fields.display_amount)/100),date:localDate(new Date(String(t.fields.occurred_at))),status:'SUCCESS',account:'',to:'',category:'其他',original:'',note:String(t.fields.note),sponsor:false,consumption:'0'} as Draft,undefined,t);return;}if(d.fail){await business({kind:'SET_STATUS',transactionId:d.fail,status:'FAILED'});await refresh();close();return;}if(d.resolve){const [i,j]=d.resolve.split(':').map(Number),c=snap.conflicts[i];await raw([{action:'RESOLVE_CONFLICT',entity:{type:c.entity_type,id:c.entity_id,fields:{[c.field]:c.candidates[j].value}}}]);await refresh();toast('冲突已解决');return;}if(d.day){const amount=activeMonth().filter(t=>dayOf(new Date(String(t.fields.occurred_at)))===Number(d.day)).reduce((sum,t)=>sum+Number(effect(t.id)?.fields.amount||0),0);toast(`${month}-${d.day} · 净消费 ¥${moneyText(snap.conflicts.length?null:amount)}`);}}catch(e){error(e);}});
document.addEventListener('change',async ev=>{const el=ev.target as HTMLInputElement;try{if(el.id==='import-account')importAccountChoice=el.value;if(el.id==='import-role')importRoleChoice=el.value;if(el.id==='remember-import')importRemember=el.checked;if(el.id==='import-group'){importGroup=el.value;render();}if(el.id==='import-show'){importShow=el.value;render();}if(el.id==='month'){month=el.value;selected.clear();render();}if(el.id==='type-filter'){typeFilter=el.value;render();}if(el.id==='account-filter'){accountFilter=el.value;render();}if(el.id==='status-filter'){statusFilter=el.value;render();}if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render();}if(el.dataset.draftSelect!==undefined){drafts[Number(el.dataset.draftSelect)].selected=el.checked;await persistQueue();}if(el.id==='display-mode'){await settings({mode:el.value});await refresh();}}catch(e){error(e);}});
let searchTimer:ReturnType<typeof setTimeout>;document.addEventListener('input',ev=>{const el=ev.target as HTMLInputElement;if(el.id==='search'){query=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=el.selectionStart;render();const input=$<HTMLInputElement>('#search');input.focus();input.setSelectionRange(pos,pos);},250);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();});window.addEventListener('online',()=>{if(state)render();});window.addEventListener('offline',()=>{if(state)render();});window.addEventListener('focus',()=>{if(state&&!dialog.open)refresh().catch(error);});
(async()=>{try{await openStore();const view=new URLSearchParams(location.search).get('view');if(view==='mobile'||view==='desktop'||view==='auto')await settings({mode:view});await refresh();if('serviceWorker'in navigator&&import.meta.env.PROD){const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});const hint=()=>{if(registration.waiting){toast('发现新版本。待办已保存，请关闭所有星账页面后重新打开。');}};hint();registration.addEventListener('updatefound',()=>registration.installing?.addEventListener('statechange',hint));}}catch(e){app.innerHTML='<div class="startup-error"><h1>暂时无法打开本地账本</h1><p>请关闭其他星账页面后重试，并允许网站存储。</p><button onclick="location.reload()">重试</button></div>';error(e);}})();

window.addEventListener('resize',()=>{if(state){const mode=state.settings.mode||'auto';document.documentElement.dataset.layout=mode==='auto'?(window.innerWidth<=800?'mobile':'desktop'):mode;}});

function setupImportAccounts(){
 refreshDrafts();const groups=accountSetupGroups(drafts,accounts(),entities('import_rules'),snap.conflicts),revision=state.importRevision||0;
 if(!groups.length){toast('资金账户已识别完成');return;}
 modal('设置导入账户',`<form id="setup-accounts-form"><p>系统已按账单整理出 ${groups.length} 个资金渠道。可以新建账户，也可绑定已有账户并调整显示名称。余额以后再补。</p>${groups.map((g,i)=>{
 const valid=accounts().filter(a=>g.items.every(({index,role})=>allowedAccount(drafts[index],a,role)));
 const choice=g.candidates.length===1?g.candidates[0]:'new';const found=accounts().find(a=>a.id===choice);
 return `<fieldset class="import-account-group"><legend>${esc(g.label)} · ${new Set(g.items.map(x=>x.index)).size} 笔</legend><small>${esc([...new Set(g.items.map(x=>drafts[x.index].platform))].join(' / '))}</small><div class="form-grid"><label>账户关联<select name="account-${i}" data-setup-choice="${i}">${opts([['new','新建账户'],...valid.map(a=>[a.id,String(a.fields.name)] as [string,string]),['later','稍后设置此渠道']],choice)}</select></label><label>账户显示名称<input name="name-${i}" maxlength="60" value="${esc(found?.fields.name||g.descriptor?.name||g.label)}" required></label><label>账户类型<select name="type-${i}" ${found?'disabled':''}>${opts([['ASSET','资产 · 钱包 / 储蓄卡'],['LIABILITY','负债 · 花呗 / 信用卡']],found?.fields.type||g.descriptor?.type||'ASSET')}</select></label></div></fieldset>`;
 }).join('')}<div class="modal-actions"><button type="button" class="secondary" data-close>稍后设置</button><button type="submit" class="primary">保存账户并应用到这些记录</button></div></form>`,true);
 const form=$<HTMLFormElement>('#setup-accounts-form');
 form.querySelectorAll<HTMLSelectElement>('[data-setup-choice]').forEach(el=>el.onchange=()=>{
  const i=Number(el.dataset.setupChoice),a=accounts().find(a=>a.id===el.value),name=form.elements.namedItem('name-'+i) as HTMLInputElement,type=form.elements.namedItem('type-'+i) as HTMLSelectElement;
  name.value=String(a?.fields.name||groups[i].descriptor?.name||groups[i].label);name.disabled=el.value==='later';type.value=String(a?.fields.type||groups[i].descriptor?.type||'ASSET');type.disabled=!!a||el.value==='later';
 });
 form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{
  const v=formData(form),choices:AccountChoice[]=groups.map((g,i)=>({key:g.key,accountId:v['account-'+i],name:v['name-'+i]||'',type:(v['type-'+i]||'ASSET') as 'ASSET'|'LIABILITY'}));
  await mutate(store=>configureImportAccounts(store,choices,revision));await refresh();close();toast('账户已设置，可直接导入已识别记录');
 });};
}
function unlinkedRefunds(){return transactions().filter(t=>t.fields.status==='SUCCESS'&&['REFUND','RETURN'].includes(String(t.fields.event_type))&&!entities('transaction_links').some(l=>l.fields.from_transaction_id===t.id));}
function reviewRefunds(){modal('退款关联',`<p>退款已经入账。关联原交易可补齐消费分类；不会再增加一次到账。</p>${unlinkedRefunds().map(t=>`<div class="trash-row"><div><strong>${esc(t.fields.display_name)}</strong><small>¥ ${moneyText(Number(t.fields.display_amount))} · ${formatTime(t.fields.occurred_at)}</small></div><button class="secondary" data-link-return="${esc(t.id)}">选择原交易</button></div>`).join('')||'<p>退款均已关联。</p>'}`,true);}
function linkReturnDialog(id:string){
 const t=getT(id);if(!t)return;
 const originals=transactions().filter(o=>o.fields.status==='SUCCESS'&&Date.parse(String(o.fields.occurred_at))<=Date.parse(String(t.fields.occurred_at))&&(t.fields.event_type==='REFUND'?o.fields.event_type==='PURCHASE':['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(o.fields.event_type))));
 modal('关联原交易',`<form id="link-return-form"><p>${esc(t.fields.display_name)} · ¥ ${moneyText(Number(t.fields.display_amount))}</p><label>原消费 / 转出<select name="original" required><option value="">请选择</option>${opts(originals.map(o=>[o.id,`${o.fields.display_name} · ¥ ${moneyText(Number(o.fields.display_amount))} · ${formatTime(o.fields.occurred_at)}`]),'')}</select></label><p class="footnote">不重复到账。系统会按原交易补齐分类和退款关系。</p><div class="modal-actions"><button type="button" class="secondary" data-close>以后再关联</button><button type="submit" class="primary">保存关联</button></div></form>`);
 const form=$<HTMLFormElement>('#link-return-form');form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{await business({kind:'LINK_RETURN',transactionId:id,originalId:formData(form).original});await refresh();close();toast('已关联，到账金额未重复计算');});};
}
function reviewSourceChange(index:number){
 const d=drafts[index],t=getT(d.transactionId||'');if(!t)return;
 modal('查看识别差异',`<form id="source-change-form"><p>${esc(t.fields.display_name)} · 来源原文保留，更正沿用原交易记录。</p><table class="change-table"><thead><tr><th>项目</th><th>当前账本</th><th>本次识别</th></tr></thead><tbody><tr><td>类型</td><td>${esc(typeNames[String(t.fields.event_type)])}</td><td>${esc(typeNames[d.kind])}</td></tr><tr><td>状态</td><td>${esc(statusNames[String(t.fields.status)])}</td><td>${esc(statusNames[d.status])}</td></tr><tr><td>金额</td><td>¥ ${moneyText(Number(t.fields.display_amount))}</td><td>¥ ${esc(d.amount)}</td></tr><tr><td>时间</td><td>${esc(formatTime(t.fields.occurred_at))}</td><td>${esc(d.date.replace('T',' '))}</td></tr></tbody></table>${d.sponsor?'<p>识别为他人代付：不影响本人账户。</p>':`<label>更正后的付款 / 到账账户<select name="account">${accountOpts(d.account,true,d.kind,'account',d.to)}</select></label>`}${['REPAYMENT','INTERNAL_TRANSFER','WITHDRAWAL'].includes(d.kind)?`<label>更正后的转入账户<select name="to">${accountOpts(d.to,true,d.kind,'to',d.account)}</select></label>`:''}<label>消费分类<select name="category">${opts([...new Set([...state.settings.categories,d.category,category(t.id)])].map(c=>[String(c),c]),category(t.id)==='其他'?d.category:category(t.id))}</select></label><div class="modal-actions"><button type="button" class="secondary" data-close>返回</button><button type="submit" class="primary">预览余额与消费变化</button></div></form>`,true);
 const form=$<HTMLFormElement>('#source-change-form'),expected=correctionSnapshot(snap.entities,t.id);
 form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{
  const v=formData(form),replacement=commandFrom({...d,...v,transactionId:t.id,name:String(t.fields.display_name),note:String(t.fields.note)});
  const command:BusinessCommand={kind:'CORRECT_IMPORTED_EVENT',transactionId:t.id,replacement,expectedSnapshot:expected,sourceId:crypto.randomUUID(),correctedAt:new Date().toISOString()};
  const changes=interpret(command,snap),after=structuredClone(snap.entities);
  for(const c of changes){const old=after.find(e=>e.type===c.entity.type&&e.id===c.entity.id);if(old)Object.assign(old.fields,c.entity.fields);else after.push(c.entity);}
  const postings=(es:Entity[])=>{const totals=new Map<string,number>();for(const e of es.filter(e=>e.type==='balance_movements'&&e.fields.transaction_id===t.id&&e.fields.amount!==0)){const id=String(e.fields.account_id||'');totals.set(id,(totals.get(id)||0)+Number(e.fields.amount));}return totals;};
  const beforeMoney=postings(snap.entities),afterMoney=postings(after),ids=[...new Set([...beforeMoney.keys(),...afterMoney.keys()])];
  const consumption=(es:Entity[])=>es.filter(e=>e.type==='consumption_effects'&&e.fields.transaction_id===t.id).reduce((sum,e)=>sum+Number(e.fields.amount),0);
  confirmAction('确认更正原记录',`<p>消费影响：¥ ${moneyText(consumption(snap.entities))} → ¥ ${moneyText(consumption(after))}</p><table class="change-table"><tr><th>账户</th><th>原变动</th><th>更正后</th></tr>${ids.map(id=>`<tr><td>${esc(accountName(id))}</td><td>¥ ${moneyText(beforeMoney.get(id)||0)}</td><td>¥ ${moneyText(afterMoney.get(id)||0)}</td></tr>`).join('')}</table><p>不新增一笔交易；保留原凭证和此次更正记录。负债账户的变动表示欠款增减。</p>`,async()=>{await business(command);},'应用更正');
 });};
}
